4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
15: 
16:   late final AnimationController _fadeController;
17: 
18:   late Future<List<CurrencyModel>> _currencyListFuture;
19: 
20:   List<CurrencyModel> _allCurrencies = [];
21: 
22:   @override
23:   void initState() {
24:     super.initState();
25:     _initAnimation();
26:     _initData();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _filteredCurrenciesNotifier.dispose();
32:     _fadeController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _fadeController = AnimationController(
38:       duration: Duration(milliseconds: 400),
39:       vsync: this,
40:     );
41:   }
42: 
43:   void _initData() {
44:     final currencyRepository = context.read<CurrencyRepository>();
45: 
46:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
47:       final List<CurrencyModel> value = page.items;
48:       _allCurrencies = value;
49:       _filteredCurrenciesNotifier = ValueNotifier(value);
50: 
51:       _fadeController.forward(); // запускаем анимацию
52: 
53:       currencyRepository.saveCurrencyList(value);
54: 
55:       return value;
56:     });
57:   }
58: 
59:   void _filterCurrencies(String query) {
60:     final String lowerQuery = query.toLowerCase();
61:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
62:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
63:     });
64: 
65:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
66:   }
67: 
68:   @override
69:   Widget build(BuildContext context) {
70:     return Scaffold(
71:       appBar: AppBar(title: Text(context.loc.currencyRate)),
72:       body: FutureBuilder(
73:         future: _currencyListFuture,
74:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
75:           final List<CurrencyModel>? data = snapshot.data;
76:           if (data == null) return const SizedBox.shrink();
77: 
78:           return FadeTransition(
79:             opacity: _fadeController.view,
80:             child: Column(
81:               children: [
82:                 Padding(
83:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
84:                   child: SearchView(onChanged: _filterCurrencies),
85:                 ),
86:                 Expanded(
87:                   child: ValueListenableBuilder<List<CurrencyModel>>(
88:                     valueListenable: _filteredCurrenciesNotifier,
89:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
90:                       return ListView.builder(
91:                         itemCount: data.length,
92:                         itemBuilder: (BuildContext context, int index) {
93:                           final CurrencyModel currency = data[index];
94: 
95:                           return Padding(
96:                             key: ValueKey(currency.id),
97:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
98:                             child: CurrencyCard(model: currency),
99:                           );
100:                         },
101:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
102:                       );
103:                     },
104:                   ),
105:                 ),
106:               ],
107:             ),
108:           );
109:         },
110:       ),
111:     );
112:   }
113: }

