import 'package:mad_flutter_practicum/domain/domain.dart';

/// Страница дашборда: показывает сводку курсов валют и ленты новостей.
class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage>
    with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Future<List<CurrencyModel>> _currenciesFuture;
  late Future<List<NewsModel>> _newsFuture;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  void _loadData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    // Параллельная загрузка: свежий курс валют + свежая лента новостей
    _currenciesFuture = currencyRepository.fetchRates(
      const CurrencyPageRequest(base: 'USD'),
    ).then((CurrencyPage page) => page.items);

    _newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currenciesFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          // Показываем прогресс-индикатор, пока грузятся данные
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<CurrencyModel> currencies = snapshot.data!;

          _scaleController.forward();

          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: currencies.length + 1, // +1 секция новостей
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
              itemBuilder: (BuildContext context, int index) {
                if (index == 0) {
                  return _buildCurrenciesSection(currencies);
                }

                // Секция новостей — загружается параллельно
                final newsFuture = _newsFuture;
                return FutureBuilder<List<NewsModel>>(
                  future: newsFuture,
                  builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> newsSnap) {
                    if (!newsSnap.hasData) {
                      return const Center(child: CircularProgressIndicator());
                    }

                    final List<NewsModel> news = newsSnap.data!;
                    return _buildNewsSection(news);
                  },
                );
              },
            ),
          );
        },
      ),
    );
  }

  Widget _buildCurrenciesSection(List<CurrencyModel> currencies) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Text(
            loc.exchangeRate,
            style: fonts.semiBold16,
          ),
        ),
        ListView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: currencies.length,
          padding: EdgeInsets.zero,
          itemBuilder: (BuildContext context, int index) {
            final CurrencyModel currency = currencies[index];

            return Padding(
              key: ValueKey(currency.id),
              padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
              child: CurrencyCard(model: currency),
            );
          },
        ),
      ],
    );
  }

  Widget _buildNewsSection(List<NewsModel> news) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Divider(height: 48),
        Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Text(
            loc.newsFeed,
            style: fonts.semiBold16,
          ),
        ),
        ListView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: news.length,
          padding: EdgeInsets.zero,
          itemBuilder: (BuildContext context, int index) {
            final NewsModel n = news[index];

            return Padding(
              key: ValueKey(n.link),
              padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 16),
              child: NewsCard(model: n),
            );
          },
        ),
      ],
    );
  }
}
