4: /// Страница дашборда: показывает сводку курсов валют и ленты новостей.
5: class DashboardPage extends StatefulWidget {
6:   const DashboardPage({super.key});
7: 
8:   @override
9:   State<DashboardPage> createState() => _DashboardPageState();
10: }
11: 
12: class _DashboardPageState extends State<DashboardPage>
13:     with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   late Future<List<CurrencyModel>> _currenciesFuture;
17:   late Future<List<NewsModel>> _newsFuture;
18: 
19:   late final AnimationController _scaleController;
20:   late final Animation<double> _scaleAnimation;
21: 
22:   @override
23:   void initState() {
24:     super.initState();
25:     _initAnimation();
26:     _loadData();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _scaleController.dispose();
32:     super.dispose();
33:   }
34: 
35:   void _initAnimation() {
36:     _scaleController = AnimationController(
37:       vsync: this,
38:       duration: const Duration(milliseconds: 200),
39:     );
40:     _scaleAnimation = _tween.animate(_scaleController);
41:   }
42: 
43:   void _loadData() {
44:     final currencyRepository = context.read<CurrencyRepository>();
45:     final newsRepository = context.read<NewsRepository>();
46: 
47:     // Параллельная загрузка: свежий курс валют + свежая лента новостей
48:     _currenciesFuture = currencyRepository.fetchRates(
49:       const CurrencyPageRequest(base: 'USD'),
50:     ).then((CurrencyPage page) => page.items);
51: 
52:     _newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
53:   }
54: 
55:   @override
56:   Widget build(BuildContext context) {
57:     final AppLocalizations loc = context.loc;
58: 
59:     return Scaffold(
60:       appBar: AppBar(title: Text(loc.dashboard)),
61:       body: FutureBuilder<List<CurrencyModel>>(
62:         future: _currenciesFuture,
63:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
64:           // Показываем прогресс-индикатор, пока грузятся данные
65:           if (!snapshot.hasData) {
66:             return const Center(child: CircularProgressIndicator());
67:           }
68: 
69:           final List<CurrencyModel> currencies = snapshot.data!;
70: 
71:           _scaleController.forward();
72: 
73:           return ScaleTransition(
74:             scale: _scaleAnimation,
75:             child: ListView.builder(
76:               itemCount: currencies.length + 1, // +1 секция новостей
77:               padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
78:               itemBuilder: (BuildContext context, int index) {
79:                 if (index == 0) {
80:                   return _buildCurrenciesSection(currencies);
81:                 }
82: 
83:                 // Секция новостей — загружается параллельно
84:                 final newsFuture = _newsFuture;
85:                 return FutureBuilder<List<NewsModel>>(
86:                   future: newsFuture,
87:                   builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> newsSnap) {
88:                     if (!newsSnap.hasData) {
89:                       return const Center(child: CircularProgressIndicator());
90:                     }
91: 
92:                     final List<NewsModel> news = newsSnap.data!;
93:                     return _buildNewsSection(news);
94:                   },
95:                 );
96:               },
97:             ),
98:           );
99:         },
100:       ),
101:     );
102:   }
103: 
104:   Widget _buildCurrenciesSection(List<CurrencyModel> currencies) {
105:     final AppLocalizations loc = context.loc;
106:     final ThemeFonts fonts = context.fonts;
107: 
108:     return Column(
109:       crossAxisAlignment: CrossAxisAlignment.start,
110:       children: [
111:         Padding(
112:           padding: const EdgeInsets.only(bottom: 8),
113:           child: Text(
114:             loc.exchangeRate,
115:             style: fonts.semiBold16,
116:           ),
117:         ),
118:         ListView.builder(
119:           shrinkWrap: true,
120:           physics: const NeverScrollableScrollPhysics(),
121:           itemCount: currencies.length,
122:           padding: EdgeInsets.zero,
123:           itemBuilder: (BuildContext context, int index) {
124:             final CurrencyModel currency = currencies[index];
125: 
126:             return Padding(
127:               key: ValueKey(currency.id),
128:               padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
129:               child: CurrencyCard(model: currency),
130:             );
131:           },
132:         ),
133:       ],
134:     );
135:   }
136: 
137:   Widget _buildNewsSection(List<NewsModel> news) {
138:     final AppLocalizations loc = context.loc;
139:     final ThemeFonts fonts = context.fonts;
